using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class BasicActorOperations
{
    private readonly NaturalMaterialEngineOperations _natural=new();private readonly Expression _settingsEquality=SettingsEquality();
    private static Expression SettingsEquality(){var expression=new Expression();expression.Parse("a == b",new[]{"a","b"});return expression;}
    public void apply_material_reference(Node3D owner,Variant value,Texture2D? albedo,bool preserveNull){var data=Resolve(owner,value);string type=data?.Get("type_id").AsString()??"";if(type=="natural_material"){apply_natural_material(owner,data!);return;}if(type=="shader_material"){apply_shader_material(owner,data!);return;}if(data==null&&preserveNull){assign_material_override(owner,null);return;}ensure_standard_material(owner);reset_standard_material(owner,albedo);if(type=="material")apply_standard_material(owner,data!);}
    public void apply_natural_material(Node3D owner,Resource data){var stored=Get(data.Get("values").AsGodotDictionary(),"material_settings",new Settings()).AsGodotDictionary();var material=owner.Get("natural_material").As<ShaderMaterial>();if(material==null){material=_natural.create_spatial_material(stored);owner.Set("natural_material",material);owner.Set("_natural_settings",stored.Duplicate(true));}else if(!_settingsEquality.Execute(new GArray{stored,owner.Get("_natural_settings")}).AsBool()){_natural.configure_spatial(material,stored);owner.Set("_natural_settings",stored.Duplicate(true));}assign_material_override(owner,material);}
    public void ensure_standard_material(Node3D owner){var material=owner.Get("material").As<StandardMaterial3D>();if(material==null){material=new_standard_material();owner.Set("material",material);}assign_material_override(owner,material);}
    public void reset_standard_material(Node3D owner,Texture2D? albedo)
    {
        var actor=owner.Get("actor").As<Resource>();bool image=actor!=null&&actor.Get("type_id").AsString()=="image_3d";var material=owner.Get("material").As<StandardMaterial3D>();material.Transparency=image?BaseMaterial3D.TransparencyEnum.Alpha:BaseMaterial3D.TransparencyEnum.Disabled;material.AlbedoTexture=albedo;material.AlbedoColor=Colors.White;material.Roughness=1;material.RoughnessTexture=null;material.Metallic=0;material.MetallicTexture=null;material.MetallicSpecular=.5f;material.EmissionEnabled=false;material.Emission=Colors.Black;material.EmissionTexture=null;material.NormalEnabled=false;material.NormalScale=1;material.Set("uv1_scale",Vector3.One);material.Set("uv1_offset",Vector3.Zero);material.Set("uv1_triplanar",false);material.Set("uv1_world_triplanar",false);material.ShadingMode=image?BaseMaterial3D.ShadingModeEnum.Unshaded:BaseMaterial3D.ShadingModeEnum.PerPixel;material.CullMode=image?BaseMaterial3D.CullModeEnum.Disabled:BaseMaterial3D.CullModeEnum.Back;material.NoDepthTest=false;
    }
    public void apply_standard_material(Node3D owner,Resource data)
    {
        var values=data.Get("values").AsGodotDictionary();var material=owner.Get("material").As<StandardMaterial3D>();var tint=Get(values,"tint",Colors.White).AsColor();tint.A*=Get(values,"opacity",1.0).AsSingle();material.AlbedoColor=tint;var albedo=texture_for_value(owner,Get(values,"albedo_map"));if(albedo!=null)material.AlbedoTexture=albedo;material.Transparency=tint.A<1?BaseMaterial3D.TransparencyEnum.Alpha:BaseMaterial3D.TransparencyEnum.Disabled;material.Roughness=Get(values,"roughness",1.0).AsSingle();material.RoughnessTexture=texture_for_value(owner,Get(values,"roughness_map",""));material.Metallic=Get(values,"metallic",0.0).AsSingle();material.MetallicTexture=texture_for_value(owner,Get(values,"metallic_map",""));material.MetallicSpecular=Get(values,"specular",.5).AsSingle();var specular=texture_for_value(owner,Get(values,"specular_map",""));material.SetMeta("specular_texture",specular!=null?Variant.From(specular):default);var normal=texture_for_value(owner,Get(values,"normal_map",""));material.NormalTexture=normal;material.NormalEnabled=normal!=null;material.NormalScale=Get(values,"normal_strength",1.0).AsSingle();var scale=Get(values,"uv_scale",Vector2.One).AsVector2();var offset=Get(values,"uv_offset",Vector2.Zero).AsVector2();material.Set("uv1_scale",new Vector3(scale.X,scale.Y,1));material.Set("uv1_offset",new Vector3(offset.X,offset.Y,0));material.Set("uv1_triplanar",Get(values,"uv_triplanar",false));material.Set("uv1_world_triplanar",Get(values,"uv_world_triplanar",false));material.EmissionEnabled=Get(values,"emission_enabled",false).AsBool();material.Emission=Get(values,"emission_color",Colors.Black).AsColor();material.EmissionTexture=texture_for_value(owner,Get(values,"emission_map",""));material.Set("emission_operator",Get(values,"emission_operator",0).AsInt32()==1?1:0);material.EmissionEnergyMultiplier=Get(values,"emission_energy",1.0).AsSingle();material.ShadingMode=Get(values,"unshaded",false).AsBool()?BaseMaterial3D.ShadingModeEnum.Unshaded:BaseMaterial3D.ShadingModeEnum.PerPixel;material.CullMode=Get(values,"double_sided",true).AsBool()?BaseMaterial3D.CullModeEnum.Disabled:BaseMaterial3D.CullModeEnum.Back;material.NoDepthTest=Get(values,"no_depth_test",false).AsBool();
    }
}
